            always_fails()
            return json.dumps({"raised": False})
        except ValueError:
            return json.dumps({"raised": True, "calls": counter["n"]})

    elif test_name == "exponential-backoff":
        delays_used = []

        @retry(max_retries=3, backoff="exponential", base_delay=0.1, jitter=False)
        def track_delays():
