    return "unknown-test"', test_cases = '[{"input":"basic-retry","expectedOutput":"{\"result\": \"ok\", \"calls\": 3}"},{"input":"max-retries","expectedOutput":"{\"raised\": true, \"calls\": 3}"},{"input":"exponential-backoff","expectedOutput":"{\"delays\": [0.1, 0.2, 0.4]}"}]', hidden_test_cases = '[{"input":"exception-filter","expectedOutput":"{\"error\": \"TypeError\", \"calls\": 1}"},{"input":"jitter","expectedOutput":"{\"jittered\": true, \"count\": 3}"}]' WHERE id = 'py-retry-decorator';

