UPDATE challenges SET starter_code = 'class SearchEngine {
  constructor() {
    this.documents = new Map();
    this.allDocs = [];
  }

  _tokenize(text) {
    return text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, '' '')
      .split(/\s+/)
      .filter(w => w.length > 0);
  }

  addDocument(id, text) {
    if (typeof text !== ''string'' || text.trim() === '''') {
      throw new Error(''Document text must be a non-empty string'');
    }

    if (this.documents.has(id)) {
      this.removeDocument(id);
    }

    this.documents.set(id, { text });
    this.allDocs.push({ id, text });
  }

  removeDocument(id) {
    const doc = this.documents.get(id);
    if (!doc) return false;

    this.documents.delete(id);
    return true;
  }

  getDocument(id) {
    const doc = this.documents.get(id);
    return doc ? doc.text : null;
  }

  search(query) {
    if (!query || typeof query !== ''string'' || query.trim() === '''') {
      return [];
    }

    const queryWords = this._tokenize(query);
    if (queryWords.length === 0) return [];

    const scores = new Map();

    for (const entry of this.allDocs) {
      const docWords = this._tokenize(entry.text);
      let score = 0;

      for (const qWord of queryWords) {
        for (const dWord of docWords) {
          if (dWord === qWord) {
            score++;
            break;
          }
        }
      }

      if (score > 0) {
        scores.set(entry.id, score);
      }
    }

    const results = [];
    for (const [id, score] of scores) {
      results.push({ id, score });
    }

    results.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      if (a.id < b.id) return -1;
      if (a.id > b.id) return 1;
      return 0;
    });

    return results;
  }

  getStats() {
    return {
      documentCount: this.documents.size,
    };
  }

  clear() {
    this.documents.clear();
    this.allDocs = [];
  }
}

